(6058218, 891699, 64929, '<td valign="top">A ribbon winner for sure!!!!  Instant Fav!  *10*</td>', 'A ribbon winner for sure!!!!  Instant Fav!  *10*', '2010-06-16 01:56:51.000000', NULL, 1),
