(6058348, 891530, 73056, '<td valign="top">Beautifully done and the colors to this place are fantastic.</td>', 'Beautifully done and the colors to this place are fantastic.', '2010-06-16 03:08:37.000000', NULL, 1),
(6058350, 891306, 73056, '<td valign="top">Great perspective and wonderful technicals.</td>', 'Great perspective and wonderful technicals.', '2010-06-16 03:09:47.000000', NULL, 1),
(6058357, 891284, 73056, '<td valign="top">Nice idea and the colors are fabulous.</td>', 'Nice idea and the colors are fabulous.', '2010-06-16 03:13:40.000000', NULL, 1),
(6058363, 891587, 86218, '<td valign="top">One of my favourite settings and places. I would def have cropped the bottom out with lines running there. Nice idea with car moving lights in this setting. Farmland field curves at bottom right would have been stronger with the crop. Nice take</td>', 'One of my favourite settings and places. I would def have cropped the bottom out with lines running there. Nice idea with car moving lights in this setting. Farmland field curves at bottom right would have been stronger with the crop. Nice take', '2010-06-16 03:19:52.000000', NULL, 1),
(6058365, 891305, 73056, '<td valign="top">That house is really a beacon. The setting is beautiful and you''ve captured it nicely.</td>', 'That house is really a beacon. The setting is beautiful and you''ve captured it nicely.', '2010-06-16 03:22:25.000000', NULL, 1),
(6058368, 891316, 73056, '<td valign="top">Fabulous perspective and you''ve shot it beautifully! Now you''ve got a perfect subject for the tilt challenge!</td>', 'Fabulous perspective and you''ve shot it beautifully! Now you''ve got a perfect subject for the tilt challenge!', '2010-06-16 03:25:23.000000', NULL, 1),
