(6058406, 891699, 73056, '<td valign="top">Love the elements in this picture. My eye goes through the entire scene. Nicely shot.</td>', 'Love the elements in this picture. My eye goes through the entire scene. Nicely shot.', '2010-06-16 03:54:12.000000', NULL, 1),
