(6058854, 890551, 111957, '<td valign="top">Excellent! The shot glass of matches on the left is a very nice touch. Gives you a feel for the effort this shot took.</td>', 'Excellent! The shot glass of matches on the left is a very nice touch. Gives you a feel for the effort this shot took.', '2010-06-16 09:58:52.000000', NULL, 1),
