(6058936, 891761, 88235, '<td valign="top">This looks like you tried to do a submission for all 3 contests going on right now. Point of color, books, and low light...</td>', 'This looks like you tried to do a submission for all 3 contests going on right now. Point of color, books, and low light...', '2010-06-16 10:58:28.000000', NULL, 1),
(6058938, 891753, 67553, '<td valign="top">Very nice!  Would love to see this on the front page!</td>', 'Very nice!  Would love to see this on the front page!', '2010-06-16 10:58:40.000000', NULL, 1),
(6059000, 891538, 118618, '<td valign="top">I''m interested to know more about this picture.  It looks like a large, calm water body with a hazy fog just above the water, but suspect it isn''t.  Did the long exposure blur out the rough water and make it appear like haze?  Wonderful photo.</td>', 'I''m interested to know more about this picture.  It looks like a large, calm water body with a hazy fog just above the water, but suspect it isn''t.  Did the long exposure blur out the rough water and make it appear like haze?  Wonderful photo.', '2010-06-16 11:26:49.000000', NULL, 1),
(6059003, 890808, 52810, '<td valign="top">This is fabulous...I love the colors and contrast.</td>', 'This is fabulous...I love the colors and contrast.', '2010-06-16 11:27:31.000000', NULL, 1);
