(6059563, 890547, 65319, '<td valign="top">Mesmerizing!  My favorite in this challenge.  Hope this one does well for you.  10.</td>', 'Mesmerizing!  My favorite in this challenge.  Hope this one does well for you.  10.', '2010-06-16 16:01:31.000000', NULL, 1),
(6059595, 891010, 17507, '<td valign="top">Great spot for a shot--would have been an excellent candidate for HDR to keep detail in the monument and get detail in the trees. Also, the color balance is very warm; could have used a bit of cooling. (6)</td>', 'Great spot for a shot--would have been an excellent candidate for HDR to keep detail in the monument and get detail in the trees. Also, the color balance is very warm; could have used a bit of cooling. (6)', '2010-06-16 16:14:46.000000', NULL, 1),
(6059598, 890996, 17507, '<td valign="top">Cool shot, great colors--really a shame about the noise. NeatImage would have helped a lot. (6)</td>', 'Cool shot, great colors--really a shame about the noise. NeatImage would have helped a lot. (6)', '2010-06-16 16:15:57.000000', NULL, 1),
(6059603, 891540, 17507, '<td valign="top">Great location for a shoot... too bad the focus is on the log in front. Composition could use some work--I don''t think the log or the foreground rock add anything here. (5)</td>', 'Great location for a shoot... too bad the focus is on the log in front. Composition could use some work--I don''t think the log or the foreground rock add anything here. (5)', '2010-06-16 16:17:51.000000', NULL, 1),
(6059605, 891322, 17507, '<td valign="top">Beautiful! The colors and textures are lovely.</td>', 'Beautiful! The colors and textures are lovely.', '2010-06-16 16:18:20.000000', NULL, 1),
(6059607, 891315, 17507, '<td valign="top">To my eye, this photo suffers from a lack of a readily identifiable focal point. The train blur to the lower right distracts from the rest of the photo. Most of the image appears underexposed. (5)</td>', 'To my eye, this photo suffers from a lack of a readily identifiable focal point. The train blur to the lower right distracts from the rest of the photo. Most of the image appears underexposed. (5)', '2010-06-16 16:19:11.000000', NULL, 1),
(6059615, 891379, 17507, '<td valign="top">I''m afraid I can''t see anything in this photograph to indicate the length of the exposure.</td>', 'I''m afraid I can''t see anything in this photograph to indicate the length of the exposure.', '2010-06-16 16:22:39.000000', NULL, 1),
(6059617, 891316, 17507, '<td valign="top">Excellent work. Cyan rarely looks this good.</td>', 'Excellent work. Cyan rarely looks this good.', '2010-06-16 16:23:15.000000', NULL, 1),
(6059623, 890816, 107410, '<td valign="top">Looks like you found one that you liked... ;-)</td>', 'Looks like you found one that you liked... ;-)', '2010-06-16 16:26:15.000000', NULL, 1),
(6059637, 890860, 80735, '<td valign="top">Excellent...</td>', 'Excellent...', '2010-06-16 16:33:45.000000', NULL, 1),
(6059667, 890804, 50641, '<td valign="top">excellent glow</td>', 'excellent glow', '2010-06-16 16:48:04.000000', NULL, 1),
(6059717, 891010, 113419, '<td valign="top">imo this should be straightened just a bit, otherwise a very nice image</td>', 'imo this should be straightened just a bit, otherwise a very nice image', '2010-06-16 17:15:59.000000', NULL, 1),
(6059725, 891236, 113419, '<td valign="top">i like the dreamy feel this has</td>', 'i like the dreamy feel this has', '2010-06-16 17:20:34.000000', NULL, 1),
(6059728, 891748, 113419, '<td valign="top">imo this would be a better image had the Eubank Blvd sign and the oncoming traffic been cropped out</td>', 'imo this would be a better image had the Eubank Blvd sign and the oncoming traffic been cropped out', '2010-06-16 17:21:53.000000', NULL, 1),
