(6060180, 890971, 117831, '<td valign="top">The size of the image is very small which makes me unable to see the image entirely. It also appears (though I cant see it well) to be very blurry)</td>', 'The size of the image is very small which makes me unable to see the image entirely. It also appears (though I cant see it well) to be very blurry)', '2010-06-16 20:07:02.000000', NULL, 1),
(6060181, 891624, 117831, '<td valign="top">there is not a "focus" on the image. IMHO the bird should of filled more of the frame</td>', 'there is not a "focus" on the image. IMHO the bird should of filled more of the frame', '2010-06-16 20:07:40.000000', NULL, 1),
(6060182, 891824, 117831, '<td valign="top">to dark for me...</td>', 'to dark for me...', '2010-06-16 20:08:28.000000', NULL, 1),
(6060184, 891588, 117831, '<td valign="top">i cant make out any part of the image...</td>', 'i cant make out any part of the image...', '2010-06-16 20:08:48.000000', NULL, 1),
(6060193, 891524, 117831, '<td valign="top">this effect makes u head look chopped off.</td>', 'this effect makes u head look chopped off.', '2010-06-16 20:11:38.000000', NULL, 1),
(6060197, 891819, 117831, '<td valign="top">nothing in focus to help pinpoint the image and make the motion stand out... it makes it hard on the eyes</td>', 'nothing in focus to help pinpoint the image and make the motion stand out... it makes it hard on the eyes', '2010-06-16 20:12:21.000000', NULL, 1),
(6060307, 891747, 107410, '<td valign="top">Looks like you missed the focus on the waterfall...</td>', 'Looks like you missed the focus on the waterfall...', '2010-06-16 21:51:24.000000', NULL, 1),
(6060312, 891236, 107410, '<td valign="top">Gild: cool word, I had to look it up. <br/> <br/>Regarding the picture, for me the water should have at least a little bit of texture. I love the colors and processing though.</td>', 'Gild: cool word, I had to look it up.  Regarding the picture, for me the water should have at least a little bit of texture. I love the colors and processing though.', '2010-06-16 21:58:23.000000', NULL, 1),
(6060313, 891747, 37845, '<td valign="top">This looks like Albion falls in Hamilton. Could be a tad sharper, and I dont like the darked sky.</td>', 'This looks like Albion falls in Hamilton. Could be a tad sharper, and I dont like the darked sky.', '2010-06-16 21:58:24.000000', NULL, 1),
(6060318, 891646, 23484, '<td valign="top">Great angle and neat colors.</td>', 'Great angle and neat colors.', '2010-06-16 22:00:28.000000', NULL, 1),
(6060320, 890477, 23484, '<td valign="top">Very nice softness.</td>', 'Very nice softness.', '2010-06-16 22:00:43.000000', NULL, 1),
(6060323, 891236, 23484, '<td valign="top">Definitely a long exposure.</td>', 'Definitely a long exposure.', '2010-06-16 22:01:16.000000', NULL, 1),
(6060324, 891405, 23484, '<td valign="top">Gorgeous city shot. Nice job.</td>', 'Gorgeous city shot. Nice job.', '2010-06-16 22:01:31.000000', NULL, 1),
(6060327, 891639, 107410, '<td valign="top">Perfect feeling of motion! Well done! 10!<br/> <br/>Out of curiosity, did you take any without the "split" sky, with the sunset as the primary background instead?</td>', 'Perfect feeling of motion! Well done! 10! Out of curiosity, did you take any without the "split" sky, with the sunset as the primary background instead?', '2010-06-16 22:02:19.000000', NULL, 1),
(6060333, 891666, 23484, '<td valign="top">Excellent train image. Nice job on the exposure.</td>', 'Excellent train image. Nice job on the exposure.', '2010-06-16 22:03:02.000000', NULL, 1),
(6060335, 891628, 23484, '<td valign="top">This is nice in B&amp;W.</td>', 'This is nice in B&W.', '2010-06-16 22:03:29.000000', NULL, 1),
(6060337, 891440, 23484, '<td valign="top">I love the high contrast.</td>', 'I love the high contrast.', '2010-06-16 22:03:55.000000', NULL, 1),
(6060339, 891040, 107410, '<td valign="top">Nice lightning shot. The focus seems to be a bit of though.</td>', 'Nice lightning shot. The focus seems to be a bit of though.', '2010-06-16 22:04:28.000000', NULL, 1),
