(6061526, 891538, 73056, '<td valign="top">Nicely shot.</td>', 'Nicely shot.', '2010-06-18 02:17:07.000000', NULL, 1),
(6061527, 891532, 73056, '<td valign="top">Great concept! I like it.</td>', 'Great concept! I like it.', '2010-06-18 02:18:56.000000', NULL, 1),
(6061528, 891756, 94241, '<td valign="top">Stunningly beautiful waterfall.  I''m honestly not a fan of using foliage to frame something though, it always strikes me as a bit of a barrier between the viewer and the subject.</td>', 'Stunningly beautiful waterfall.  I''m honestly not a fan of using foliage to frame something though, it always strikes me as a bit of a barrier between the viewer and the subject.', '2010-06-18 02:20:01.000000', NULL, 1),
(6061536, 891591, 19959, '<td valign="top">Very good... but not as good as the original version of this idea IMO</td>', 'Very good... but not as good as the original version of this idea IMO', '2010-06-18 02:46:25.000000', NULL, 1),
(6061571, 890469, 107410, '<td valign="top">My #1! Awesome work! 10!</td>', 'My #1! Awesome work! 10!', '2010-06-18 04:10:45.000000', NULL, 1),
(6061579, 891532, 63812, '<td valign="top">very good!</td>', 'very good!', '2010-06-18 04:32:22.000000', NULL, 1),
(6061580, 891278, 63812, '<td valign="top">awesome!</td>', 'awesome!', '2010-06-18 04:32:28.000000', NULL, 1),
(6061593, 890843, 47470, '<td valign="top">I love the painterly feeling of this.  The colors are gorgeous and her expression is intriguing.</td>', 'I love the painterly feeling of this.  The colors are gorgeous and her expression is intriguing.', '2010-06-18 05:15:54.000000', NULL, 1),
(6061594, 891305, 77149, '<td valign="top">Thankfully, I can always count on the Icelandic entries to bring some quality to the competition - assuming that my assumptions are correct, of course!  Lovely picture - thank you. I would like to see a closer crop as well, from a viewpoint slightly over to the right so as to separate the two tors in the left foreground. But one can get picky when trying to find suggestions!</td>', 'Thankfully, I can always count on the Icelandic entries to bring some quality to the competition - assuming that my assumptions are correct, of course!  Lovely picture - thank you. I would like to see a closer crop as well, from a viewpoint slightly over to the right so as to separate the two tors in the left foreground. But one can get picky when trying to find suggestions!', '2010-06-18 05:17:52.000000', NULL, 1),
(6061595, 890996, 77149, '<td valign="top">I love the concept and the structure, but the NOISE!!! Shame...I can''t do decent long exposures on my camera without getting that sort of thing either...</td>', 'I love the concept and the structure, but the NOISE!!! Shame...I can''t do decent long exposures on my camera without getting that sort of thing either...', '2010-06-18 05:20:35.000000', NULL, 1),
(6061600, 891646, 77149, '<td valign="top">I love this - but I personally wish that the greenish yellow cast to the stone tunnel was a more complimentary match with the Countach.</td>', 'I love this - but I personally wish that the greenish yellow cast to the stone tunnel was a more complimentary match with the Countach.', '2010-06-18 05:40:35.000000', NULL, 1),
(6061603, 891848, 77149, '<td valign="top">Love it - the things photographers make models do!  :-)  Great concept</td>', 'Love it - the things photographers make models do!  :-)  Great concept', '2010-06-18 05:41:55.000000', NULL, 1),
(6061604, 891615, 86218, '<td valign="top">Love it. Would love to see the exposure time on this.</td>', 'Love it. Would love to see the exposure time on this.', '2010-06-18 05:43:05.000000', NULL, 1),
(6061605, 891747, 77149, '<td valign="top">I like the setup, but I think the effect is far too soft. Was the camera stable?</td>', 'I like the setup, but I think the effect is far too soft. Was the camera stable?', '2010-06-18 05:43:17.000000', NULL, 1),
(6061609, 891204, 117153, '<td valign="top">Really nice idea - very creative.</td>', 'Really nice idea - very creative.', '2010-06-18 06:15:50.000000', NULL, 1),
(6061612, 891305, 117153, '<td valign="top">Lovely shot, the red roof really pops.</td>', 'Lovely shot, the red roof really pops.', '2010-06-18 06:41:42.000000', NULL, 1),
(6061615, 891395, 117153, '<td valign="top">Nice.</td>', 'Nice.', '2010-06-18 06:55:46.000000', NULL, 1),
(6061638, 891316, 23484, '<td valign="top">What a great perspective. Great colors.</td>', 'What a great perspective. Great colors.', '2010-06-18 08:04:20.000000', NULL, 1),
(6061639, 891736, 23484, '<td valign="top">I love the starkness.</td>', 'I love the starkness.', '2010-06-18 08:04:54.000000', NULL, 1),
(6061640, 891567, 23484, '<td valign="top">Excellent job and great title.</td>', 'Excellent job and great title.', '2010-06-18 08:05:47.000000', NULL, 1),
(6061643, 891558, 23484, '<td valign="top">Nice colors and good job on the exposure.</td>', 'Nice colors and good job on the exposure.', '2010-06-18 08:06:12.000000', NULL, 1),
(6061680, 891646, 117418, '<td valign="top">nice car</td>', 'nice car', '2010-06-18 09:21:53.000000', NULL, 1),
(6061704, 891239, 117717, '<td valign="top">love the mood, the colours, your use of the long exposure... my favourite.</td>', 'love the mood, the colours, your use of the long exposure... my favourite.', '2010-06-18 09:53:24.000000', NULL, 1),
(6061799, 891389, 110792, '<td valign="top">this isn''t a long exposure shot</td>', 'this isn''t a long exposure shot', '2010-06-18 12:01:52.000000', NULL, 1),
(6061811, 891699, 3102, '<td valign="top">Now THERE is an awesome shot!  I will be shocked if this isn''t wearing a blue ribbon at the end of the week.  Beautiful!</td>', 'Now THERE is an awesome shot!  I will be shocked if this isn''t wearing a blue ribbon at the end of the week.  Beautiful!', '2010-06-18 12:21:24.000000', NULL, 1),
(6061814, 891010, 3102, '<td valign="top">This would be excellent if it had been rotated clockwise just a hair.</td>', 'This would be excellent if it had been rotated clockwise just a hair.', '2010-06-18 12:26:32.000000', NULL, 1),
(6061897, 891690, 83313, '<td valign="top">Almost missed the person in the scene!</td>', 'Almost missed the person in the scene!', '2010-06-18 14:49:05.000000', NULL, 1),
(6061899, 891747, 83313, '<td valign="top">Tonemapping seems a little overdone to me.</td>', 'Tonemapping seems a little overdone to me.', '2010-06-18 14:51:25.000000', NULL, 1),
(6062098, 891379, 46832, '<td valign="top">Interesting twist on the subject.</td>', 'Interesting twist on the subject.', '2010-06-18 18:46:02.000000', NULL, 1),
(6062100, 890971, 46832, '<td valign="top">It could be an interesting photo but needs to be bigger.</td>', 'It could be an interesting photo but needs to be bigger.', '2010-06-18 18:47:10.000000', NULL, 1),
(6062111, 891322, 46832, '<td valign="top"><u></u></td>', '', '2010-06-18 18:53:58.000000', NULL, 1),
(6062190, 891316, 117474, '<td valign="top">This is a great shot. I like the... subtle use of long exposure here.</td>', 'This is a great shot. I like the... subtle use of long exposure here.', '2010-06-18 20:29:15.000000', NULL, 1),
(6062193, 890804, 117474, '<td valign="top">I like these kinds of photos, repeated symmetry going down the ranks. <br/>Personally, I''d''ve preferred the lights going down the centre of the picture. So if the shot was taken half a metre or so to the left.</td>', 'I like these kinds of photos, repeated symmetry going down the ranks. Personally, I''d''ve preferred the lights going down the centre of the picture. So if the shot was taken half a metre or so to the left.', '2010-06-18 20:30:53.000000', NULL, 1),
(6062196, 891506, 117474, '<td valign="top">Very nice fountain. <br/>I noticed there were trees in the background. I don''t know if they''d''ve fitted the shape, but it might have been nice to have the black of the tree frame the shape of the fountain itself. I find the trees in the background distracting as they are I''m afraid.</td>', 'Very nice fountain. I noticed there were trees in the background. I don''t know if they''d''ve fitted the shape, but it might have been nice to have the black of the tree frame the shape of the fountain itself. I find the trees in the background distracting as they are I''m afraid.', '2010-06-18 20:37:16.000000', NULL, 1),
(6062202, 891587, 117474, '<td valign="top">I see what you''re doing. The isolation''s nice. I don''t think the singlestreak of light fits the landscape. Of course that''s what you were trying to get. Maybe if it had continued along the whole road I''d''ve liked the shot more, but then again that wouldn''t bring out the isolation that you''re trying to bring up.</td>', 'I see what you''re doing. The isolation''s nice. I don''t think the singlestreak of light fits the landscape. Of course that''s what you were trying to get. Maybe if it had continued along the whole road I''d''ve liked the shot more, but then again that wouldn''t bring out the isolation that you''re trying to bring up.', '2010-06-18 20:41:37.000000', NULL, 1),
(6062203, 891651, 117474, '<td valign="top">I know the longer exposure is meant to enhance the sense of motion for a wedding dance... The motion in this picture is such that nothing is really in a nice crisp focus, but things aren''t ''blurry'' enough so that I know it was a LE shot. <br/>As a result I think it makes it look more like... an accidental long exposure than an intentionally planned one... <br/>Basically I think the exposure should have been longer so I wouldn''t think this. <br/> <br/>I''m far from an expert in this. But it''s what I got from the photo.</td>', 'I know the longer exposure is meant to enhance the sense of motion for a wedding dance... The motion in this picture is such that nothing is really in a nice crisp focus, but things aren''t ''blurry'' enough so that I know it was a LE shot. As a result I think it makes it look more like... an accidental long exposure than an intentionally planned one... Basically I think the exposure should have been longer so I wouldn''t think this.  I''m far from an expert in this. But it''s what I got from the photo.', '2010-06-18 20:48:28.000000', NULL, 1),
(6062204, 891540, 117474, '<td valign="top">That''s a fascinating fallen tree. I think maybe too much so that it takes the eye away from the true subject of long exposure. When I look at one I want to dart to the other. <br/>I like the title.</td>', 'That''s a fascinating fallen tree. I think maybe too much so that it takes the eye away from the true subject of long exposure. When I look at one I want to dart to the other. I like the title.', '2010-06-18 20:50:12.000000', NULL, 1),
(6062206, 890996, 117474, '<td valign="top">It''s a shame about the grainy aspect on the river and banks.</td>', 'It''s a shame about the grainy aspect on the river and banks.', '2010-06-18 20:54:54.000000', NULL, 1),
(6062207, 890804, 76335, '<td valign="top">Beautiful space and depth. I like the two-tone effect.</td>', 'Beautiful space and depth. I like the two-tone effect.', '2010-06-18 20:58:33.000000', NULL, 1),
(6062208, 891146, 76335, '<td valign="top">I wish the trees had a bit more shadow detail. Nice scene anyway.</td>', 'I wish the trees had a bit more shadow detail. Nice scene anyway.', '2010-06-18 20:59:04.000000', NULL, 1),
(6062209, 890843, 76335, '<td valign="top">Intriguing. The colors are almost ghoulish. Love it!</td>', 'Intriguing. The colors are almost ghoulish. Love it!', '2010-06-18 20:59:37.000000', NULL, 1),
(6062210, 890808, 76335, '<td valign="top">Kind of a cliche, but this is pretty good. The rides carved out some interesting shapes.</td>', 'Kind of a cliche, but this is pretty good. The rides carved out some interesting shapes.', '2010-06-18 21:00:42.000000', NULL, 1),
(6062211, 890807, 117474, '<td valign="top">You caught a shooting star. Very nice.</td>', 'You caught a shooting star. Very nice.', '2010-06-18 21:01:07.000000', NULL, 1),
(6062212, 890996, 76335, '<td valign="top">I rather like the graininess.</td>', 'I rather like the graininess.', '2010-06-18 21:01:08.000000', NULL, 1),
(6062213, 891239, 76335, '<td valign="top">The vignette feels kind of artificial. But the scene more than makes up for it. Really nice.</td>', 'The vignette feels kind of artificial. But the scene more than makes up for it. Really nice.', '2010-06-18 21:02:21.000000', NULL, 1),
(6062216, 891824, 76335, '<td valign="top">Love the low-key treatment and the grain. Great idea.</td>', 'Love the low-key treatment and the grain. Great idea.', '2010-06-18 21:02:50.000000', NULL, 1),
(6062217, 891826, 76335, '<td valign="top">Pretty wild stuff. Took me a second to find the second horse.</td>', 'Pretty wild stuff. Took me a second to find the second horse.', '2010-06-18 21:03:26.000000', NULL, 1),
(6062218, 891501, 76335, '<td valign="top">Beautifully done. The foreground textures complement the smoothness of the water very effectively.</td>', 'Beautifully done. The foreground textures complement the smoothness of the water very effectively.', '2010-06-18 21:04:03.000000', NULL, 1),
(6062219, 891567, 117474, '<td valign="top">Don''t like the cows too much, I''m afraid. The trees are magnificent with the sky background.</td>', 'Don''t like the cows too much, I''m afraid. The trees are magnificent with the sky background.', '2010-06-18 21:04:12.000000', NULL, 1),
(6062221, 891694, 76335, '<td valign="top">This is fabulous!</td>', 'This is fabulous!', '2010-06-18 21:05:13.000000', NULL, 1),
(6062222, 891808, 76335, '<td valign="top">Infrared? I like the tight framing which forces the eye to reckon with the chaotic textures.</td>', 'Infrared? I like the tight framing which forces the eye to reckon with the chaotic textures.', '2010-06-18 21:05:57.000000', NULL, 1),
(6062224, 891839, 76335, '<td valign="top">Simple and quiet. Well done.</td>', 'Simple and quiet. Well done.', '2010-06-18 21:06:32.000000', NULL, 1),
(6062225, 891573, 76335, '<td valign="top">Works well in black and white.</td>', 'Works well in black and white.', '2010-06-18 21:07:11.000000', NULL, 1),
(6062226, 891808, 117474, '<td valign="top">I think the B&amp;W makes it a little too difficult to find the waves.</td>', 'I think the B&W makes it a little too difficult to find the waves.', '2010-06-18 21:07:33.000000', NULL, 1),
(6062227, 891535, 76335, '<td valign="top">Now for something completely different... <br/> <br/>Great idea. Nicely executed.</td>', 'Now for something completely different...  Great idea. Nicely executed.', '2010-06-18 21:08:02.000000', NULL, 1),
(6062228, 891549, 76335, '<td valign="top">I love the composition, and the grain is even okay. But it feels way too sharp.</td>', 'I love the composition, and the grain is even okay. But it feels way too sharp.', '2010-06-18 21:09:38.000000', NULL, 1),
(6062229, 891283, 117474, '<td valign="top">Second shooting star of the competition, I think.</td>', 'Second shooting star of the competition, I think.', '2010-06-18 21:10:24.000000', NULL, 1),
(6062238, 889911, 36689, '<td valign="top">I am not sure if this is long exposure. Maybe it is. But the pic is spectacular.</td>', 'I am not sure if this is long exposure. Maybe it is. But the pic is spectacular.', '2010-06-18 21:19:42.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6062244, 891040, 113772, '<td valign="top">Nice Capture.</td>', 'Nice Capture.', '2010-06-18 21:29:55.000000', NULL, 1),
(6062317, 891651, 76335, '<td valign="top">I like the colors and the softness. Does feel more like a captured long moment rather than just a snapshot in time.</td>', 'I like the colors and the softness. Does feel more like a captured long moment rather than just a snapshot in time.', '2010-06-18 23:39:42.000000', NULL, 1),
(6062318, 891552, 76335, '<td valign="top">Powerful in its minimalism. I''ll be coming back for a second look.</td>', 'Powerful in its minimalism. I''ll be coming back for a second look.', '2010-06-18 23:40:18.000000', NULL, 1),
(6062319, 891615, 76335, '<td valign="top">Why do these never get old? Just excellent.</td>', 'Why do these never get old? Just excellent.', '2010-06-18 23:41:00.000000', NULL, 1),
(6062372, 891440, 60899, '<td valign="top">I am a sucker for B/W ... 9</td>', 'I am a sucker for B/W ... 9', '2010-06-19 01:47:58.000000', NULL, 1),
(6062378, 891736, 26160, '<td valign="top">almost like a dream</td>', 'almost like a dream', '2010-06-19 01:56:29.000000', NULL, 1),
(6062440, 891284, 22459, '<td valign="top">I like the image but the border kills the overall impact.</td>', 'I like the image but the border kills the overall impact.', '2010-06-19 05:14:27.000000', NULL, 1),
(6062456, 891146, 22459, '<td valign="top">nice image let down by the sky</td>', 'nice image let down by the sky', '2010-06-19 06:48:04.000000', NULL, 1),
(6062461, 891684, 118618, '<td valign="top">I find the city scene in the background to be very good.  I just don''t care for the choice of foreground subject.  I find few things less appealing than man-made wavebreaks along the coast.  I also find the antenna in the upper right to look out of place.  But, I suppose that''s just personal preference.  I think you''re on to something with that city view background.  I''d try it again with a more interesting foreground subject.</td>', 'I find the city scene in the background to be very good.  I just don''t care for the choice of foreground subject.  I find few things less appealing than man-made wavebreaks along the coast.  I also find the antenna in the upper right to look out of place.  But, I suppose that''s just personal preference.  I think you''re on to something with that city view background.  I''d try it again with a more interesting foreground subject.', '2010-06-19 07:31:23.000000', NULL, 1),
(6062464, 891699, 118618, '<td valign="top">Like many of the "soft water" photos in these Long Exposure contests, start trail photos start to get repetitious and boring.  The key is an interesting foreground.  Aside from the blurring evergreen (I assume from mountaintop winds), your foreground caught my attention.  Interesting pic.</td>', 'Like many of the "soft water" photos in these Long Exposure contests, start trail photos start to get repetitious and boring.  The key is an interesting foreground.  Aside from the blurring evergreen (I assume from mountaintop winds), your foreground caught my attention.  Interesting pic.', '2010-06-19 07:47:13.000000', NULL, 1),
(6062554, 891259, 108040, '<td valign="top">Cool</td>', 'Cool', '2010-06-19 11:22:30.000000', NULL, 1),
(6062605, 891748, 76335, '<td valign="top">A bit of a cliche, but I do like this. Good DOF and like the cool evening colors.</td>', 'A bit of a cliche, but I do like this. Good DOF and like the cool evening colors.', '2010-06-19 12:24:10.000000', NULL, 1),
(6062606, 891848, 76335, '<td valign="top">I wish she were a bit closer. Focus on her is a bit soft (or maybe she moved). Great idea though.</td>', 'I wish she were a bit closer. Focus on her is a bit soft (or maybe she moved). Great idea though.', '2010-06-19 12:25:06.000000', NULL, 1),
(6062608, 891699, 76335, '<td valign="top">Very intriguing and profesionally done.</td>', 'Very intriguing and profesionally done.', '2010-06-19 12:26:22.000000', NULL, 1),
(6062623, 891761, 118315, '<td valign="top">This is nice.</td>', 'This is nice.', '2010-06-19 12:46:23.000000', NULL, 1),
(6062624, 891810, 118315, '<td valign="top">Nice panning.</td>', 'Nice panning.', '2010-06-19 12:46:26.000000', NULL, 1),
(6062625, 891848, 118315, '<td valign="top">Nice effect.</td>', 'Nice effect.', '2010-06-19 12:46:36.000000', NULL, 1),
(6062626, 891699, 118315, '<td valign="top">Nice.</td>', 'Nice.', '2010-06-19 12:46:46.000000', NULL, 1),
(6062740, 890477, 76185, '<td valign="top">Very atmospheric, fantastic location and I love the warm sun colours with the cold looking mist. I''d be tempted to have cropped out the tree at the bottom, particulary with the blured branches as it seems a little distracting?</td>', 'Very atmospheric, fantastic location and I love the warm sun colours with the cold looking mist. I''d be tempted to have cropped out the tree at the bottom, particulary with the blured branches as it seems a little distracting?', '2010-06-19 17:23:29.000000', NULL, 1),
(6062743, 890778, 76185, '<td valign="top">Great Fireworks shot!</td>', 'Great Fireworks shot!', '2010-06-19 17:26:03.000000', NULL, 1),
(6062744, 891684, 76185, '<td valign="top">Love the misty cityscape, I thkn the tones work well here.</td>', 'Love the misty cityscape, I thkn the tones work well here.', '2010-06-19 17:26:54.000000', NULL, 1),
(6062745, 890996, 76185, '<td valign="top">Great star trails here. Not sure if the noise distracts a little too much?</td>', 'Great star trails here. Not sure if the noise distracts a little too much?', '2010-06-19 17:28:38.000000', NULL, 1),
(6062748, 891527, 76185, '<td valign="top">Great sky capture, and I like the silhouetted landscape framing here.</td>', 'Great sky capture, and I like the silhouetted landscape framing here.', '2010-06-19 17:31:27.000000', NULL, 1),
(6062749, 891826, 76185, '<td valign="top">Like the setup here, although perhaps not really a long exposure? I think if the focus were on the horses head it would give a lot more impact.</td>', 'Like the setup here, although perhaps not really a long exposure? I think if the focus were on the horses head it would give a lot more impact.', '2010-06-19 17:33:40.000000', NULL, 1),
(6062751, 891699, 76185, '<td valign="top">Great landscape for this star trails shot. The colours give this a cold feeling which is a pleasing contrast to many of the other entries.</td>', 'Great landscape for this star trails shot. The colours give this a cold feeling which is a pleasing contrast to many of the other entries.', '2010-06-19 17:35:35.000000', NULL, 1),
(6062752, 891146, 76185, '<td valign="top">Love the sense of scale here, although wish the background wasn''t quite so washed out as it would be good to see those mountains a little clearer.</td>', 'Love the sense of scale here, although wish the background wasn''t quite so washed out as it would be good to see those mountains a little clearer.', '2010-06-19 17:36:54.000000', NULL, 1),
(6062754, 891278, 76185, '<td valign="top">I like the mirroring of the fireflies and the stars. The large expanse of black in the lower right is perhaps a little off balancing though?</td>', 'I like the mirroring of the fireflies and the stars. The large expanse of black in the lower right is perhaps a little off balancing though?', '2010-06-19 17:40:07.000000', NULL, 1),
(6062771, 891780, 76335, '<td valign="top">Beautifully intricate. Nice work.</td>', 'Beautifully intricate. Nice work.', '2010-06-19 18:02:17.000000', NULL, 1),
(6062772, 891440, 76335, '<td valign="top">Nice contrast and textures. Looks good in black and white.</td>', 'Nice contrast and textures. Looks good in black and white.', '2010-06-19 18:02:34.000000', NULL, 1),
(6062773, 890812, 76335, '<td valign="top">Not bad. Might have worked better in black and white.</td>', 'Not bad. Might have worked better in black and white.', '2010-06-19 18:03:23.000000', NULL, 1),
(6062774, 891810, 76335, '<td valign="top">Good panning here. Great sense of motion.</td>', 'Good panning here. Great sense of motion.', '2010-06-19 18:04:54.000000', NULL, 1),
(6062822, 891794, 76335, '<td valign="top">Nice feeling of fast motion. The little bit of color adds interest.</td>', 'Nice feeling of fast motion. The little bit of color adds interest.', '2010-06-19 20:11:43.000000', NULL, 1),
(6062823, 890400, 76335, '<td valign="top">Excellent composition. Good shadow detail and exposure all around.</td>', 'Excellent composition. Good shadow detail and exposure all around.', '2010-06-19 20:12:26.000000', NULL, 1),
(6062824, 890469, 76335, '<td valign="top">Good job staging this! Comes off like a short movie -- or maybe just a bad dream. <br/> <br/>Good luck (if this is you).</td>', 'Good job staging this! Comes off like a short movie -- or maybe just a bad dream.  Good luck (if this is you).', '2010-06-19 20:13:23.000000', NULL, 1),
(6062825, 891567, 76335, '<td valign="top">Hilarious. Nicely conceived, nicely executed.</td>', 'Hilarious. Nicely conceived, nicely executed.', '2010-06-19 20:13:55.000000', NULL, 1),
(6062826, 891531, 76335, '<td valign="top">Interesting that you chose to do this in black and white. It works for me.</td>', 'Interesting that you chose to do this in black and white. It works for me.', '2010-06-19 20:16:11.000000', NULL, 1),
(6062827, 891316, 76335, '<td valign="top">This feels HUGE! Incredible job.</td>', 'This feels HUGE! Incredible job.', '2010-06-19 20:16:49.000000', NULL, 1),
(6062828, 891684, 76335, '<td valign="top">Nicely composed. Good contrast, exposure.</td>', 'Nicely composed. Good contrast, exposure.', '2010-06-19 20:17:26.000000', NULL, 1),
